class RadialGrad {
  constructor(x, y, r, clr) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.clr = (typeof clr === 'string' || clr instanceof String) ? color(clr) : clr;
    this.fadedClr = color(red(window.color(this.clr)), green(window.color(this.clr)), blue(window.color(this.clr)), 0);
    this.vx = random(-5, 5);
    this.vy = random(-5, 5);
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;

    if (this.x < 0 || this.x > width-1) this.vx *= -1;
    if (this.y < 0 || this.y > height-1) this.vy *= -1;
  }

  show() {
    push();
    const gradient = drawingContext.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.r);

    // Add three color stops
    gradient.addColorStop(0, this.clr);
    // gradient.addColorStop(0.15, this.clr);
    gradient.addColorStop(1, this.fadedClr);

    // Set the fill style and draw a rectangle
    drawingContext.fillStyle = gradient;
    circle(this.x, this.y, this.r+this.r);
    pop();
  }
}

