/*
	Smoothen #WCCChallenge Filter 250417 
	https://openprocessing.org/sketch/2618183
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	inspired by Patts Video Pastel Gradient Screensaver
	https://www.youtube.com/watch?v=Mdt81-7-U18&t=433s

	The standard POSTERIZE filter() from p5js is doing a great job,
	to limit the number of calues per color channel.
	So interesting patterns occure, while the gradients are meandering.

	Vie clipping the sketch is reversed to keep an smoothed area at mouse position.
	Cann be switched on/off via LMB and resized with the mouse wheel.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let spots, showGlass = true, glassSize = 100, filterPostChanLimit = 3;
let fipDuoTone, fipGlitch, fipHalftone; // not in use https://prontopablo.github.io/p5.FIP/

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("meandering seperated colored areas with poster colores with an glass overlay at mouse position which smoothens the colores");
	frameRate(30);

	noStroke();
	fill(255);

	glassSize = (width + height) / 8;
	filterPostChanLimit = random([3, 4]);

	spots = [];
	for (let i = 0; i < 10; i++) {
		spots.push(
			new RadialGrad(
				random(0.1, 0.9) * width, 
				random(0.1, 0.9) * height, 
				random(300, 500), 
				random(["darkred", "deeppink", "navy", "darkorange"])
			)
		);
	}

	// fip filters
	fipDuoTone = createFilterShader(fip.duoTone);
	fipGlitch = createFilterShader(fip.glitch);
	fipHalftone = createFilterShader(fip.halftone);

	showCursorOrNot();
}

function showCursorOrNot() {
	if (showGlass) {
		noCursor();
	} else {
		cursor();
	}
}

function draw() {
	background(32);

	// generate moving gradient
	for (const spot of spots) {
		spot.show();
		spot.update();
	}

	// apply circle grid
	const MAR = 60,
		SZE = 25;
	if (false)
		for (let y = MAR - SZE / 2; y < height; y += MAR) {
			for (let x = MAR - SZE / 2; x < width; x += MAR) {
				circle(x, y, SZE);
			}
		}

	// apply filter
	push()
	beginClip({
		invert: true
	});
	circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), showGlass ? glassSize : 0);
	endClip();

	// filter(INVERT);
	// filter(GRAY);
	// filter(THRESHOLD, 0.2); // map(sin(frameCount/15), -1, 1, 0.1, 0.5)
	filter(POSTERIZE, filterPostChanLimit);

	fipDuoTone.setUniform('tone1', [0.8627, 0.6275, 0.0]);
	fipDuoTone.setUniform('tone2', [0.4157, 0.0118, 0.5647]);
	// filter(fipDuoTone);

	fipGlitch.setUniform('glitchIntensity', 2.8); // Set the intensity of the glitch effect
	// filter(fipGlitch);

	fipHalftone.setUniform('cellSize', 4.0);
	fipHalftone.setUniform('threshold', 0.2);
	// filter(fipHalftone);
	pop()
}

// interactions
function mouseWheel(event) {
	glassSize -= event.delta; // Math.sign(event.delta)*5;
	return false;
}

function mousePressed() {
	if (mouseButton != RIGHT) showGlass = !showGlass;
	showCursorOrNot()
}

function doubleClicked() {
	if (mouseButton != RIGHT) setup();
}
